package com.crosscheck.controller;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.*;import org.springframework.beans.BeanUtils;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;import org.springframework.web.server.ResponseStatusException;import java.util.stream.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.core.type.TypeReference;
@RestController @RequestMapping("/api/candidates") public class CandidateController{
 private final CandidateRepository repo;private final DocumentRepository docs;private final AuthService auth;private final RiskEngineService risk;private final AuditService audit;private final EmailService emailService;private final ObjectMapper objectMapper;@Value("${crosscheck.upload-dir}") private String uploadDir;
 public CandidateController(CandidateRepository r,DocumentRepository d,AuthService a,RiskEngineService e,AuditService l,EmailService mail,ObjectMapper mapper){repo=r;docs=d;auth=a;risk=e;audit=l;emailService=mail;objectMapper=mapper;}
 @GetMapping public List<Candidate> all(@RequestHeader(value="Authorization",required=false)String h,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="")String risk){auth.require(h);String q=search.toLowerCase();return repo.findAllByOrderByCreatedAtDesc().stream().filter(c->risk.isBlank()||risk.equalsIgnoreCase(c.getRiskLevel())).filter(c->q.isBlank()||String.join(" ",n(c.getName()),n(c.getEmail()),n(c.getPosition()),n(c.getSkills())).toLowerCase().contains(q)).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){auth.require(h);Candidate c=repo.findById(id).orElseThrow();Map<String,Object> m=objectMapper.convertValue(c, new TypeReference<Map<String,Object>>(){});m.put("documents",docs.findByCandidateIdOrderByUploadedAtDesc(id));Map<String,Object> factors=new LinkedHashMap<>();factors.put("Duplicate Profile",c.isDuplicateEmail()||c.isDuplicateMobile()?"Detected":"Clear");factors.put("Multiple Offers",c.getActiveOffers());factors.put("Employment Gap",c.getEmploymentGapMonths()+" months");factors.put("Notice Period",c.getNoticePeriodDays()+" days");factors.put("Identity",n(c.getIdentityStatus()).isBlank()?"PENDING":c.getIdentityStatus());factors.put("Education",n(c.getEducationStatus()).isBlank()?"PENDING":c.getEducationStatus());factors.put("Offer Letter",n(c.getOfferLetterStatus()).isBlank()?"PENDING":c.getOfferLetterStatus());m.put("riskFactors",factors);m.put("activities",List.of(Map.of("action","Candidate profile reviewed","createdAt",String.valueOf(c.getUpdatedAt())),Map.of("action","Risk score recalculated","createdAt",String.valueOf(c.getUpdatedAt()))));return m;}
 @PostMapping public Candidate create(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Candidate c){User u=auth.require(h);c.setId(null);c.setCreatedByUserId(u.getId());c.setCreatedByName(u.getName());c.setDuplicateEmail(repo.findAll().stream().anyMatch(x->x.getEmail()!=null&&x.getEmail().equalsIgnoreCase(c.getEmail())));c.setDuplicateMobile(repo.findAll().stream().anyMatch(x->Objects.equals(x.getMobileNumber(),c.getMobileNumber())));risk.calculate(c);Candidate saved=repo.save(c);audit.audit(u.getName(),"CANDIDATE_CREATED","CANDIDATE",saved.getId().toString(),saved.getName()+" added");audit.notify("Candidate added",saved.getName()+" was added for verification.",saved.getRiskLevel());if("HIGH".equals(saved.getRiskLevel()))audit.notify("High-risk candidate",saved.getName()+" requires urgent review.","HIGH");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Candidate Added - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Profile Added","The profile was added by "+u.getName()+" and is now pending verification."));return saved;}
 @PutMapping("/{id}") public Candidate update(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody Candidate in){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();Long keep=c.getId();var created=c.getCreatedAt();assertCanModify(u,c);BeanUtils.copyProperties(in,c,"id","createdAt","updatedAt","createdByUserId","createdByName");c.setId(keep);c.setDuplicateEmail(repo.existsByEmailIgnoreCaseAndIdNot(c.getEmail(),id));c.setDuplicateMobile(repo.existsByMobileNumberAndIdNot(c.getMobileNumber(),id));risk.calculate(c);Candidate saved=repo.save(c);audit.audit(u.getName(),"CANDIDATE_UPDATED","CANDIDATE",id.toString(),saved.getName()+" updated");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Candidate Updated - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Profile Updated","The profile information was revised by "+u.getName()+"."));return saved;}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();assertCanModify(u,c);repo.delete(c);audit.audit(u.getName(),"CANDIDATE_DELETED","CANDIDATE",id.toString(),c.getName()+" deleted");return ResponseEntity.noContent().build();}
 @PutMapping("/{id}/verification") public Candidate verify(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody Map<String,String>b){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();if(b.get("employmentStatus")!=null)c.setEmploymentStatus(b.get("employmentStatus"));if(b.get("educationStatus")!=null)c.setEducationStatus(b.get("educationStatus"));if(b.get("identityStatus")!=null)c.setIdentityStatus(b.get("identityStatus"));if(b.get("verificationStatus")!=null)c.setVerificationStatus(b.get("verificationStatus"));risk.calculate(c);repo.save(c);audit.audit(u.getName(),"VERIFICATION_UPDATED","CANDIDATE",id.toString(),"Verification status changed");audit.notify("Verification completed",c.getName()+" verification status is "+c.getVerificationStatus()+".","LOW");emailService.sendToAll(Arrays.asList(c.getEmail(),u.getEmail()),"CrossCheck Verification Update - "+c.getName(),emailService.candidateMessage(c.getName(),"Verification Status Updated","Current verification status: "+n(c.getVerificationStatus())+". Employment: "+n(c.getEmploymentStatus())+", Education: "+n(c.getEducationStatus())+", Identity: "+n(c.getIdentityStatus())+"."));return c;}
 @PutMapping("/{id}/offer-verification") public Candidate verifyOffer(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody Map<String,String>b){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();String status=n(b.get("status")).toUpperCase();if(!Set.of("VERIFIED","PENDING","FAILED","MISMATCH").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Offer Letter Status.");if(!"PENDING".equals(status)&&n(c.getOfferLetterData()).isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload The Offer Letter Before Verification.");if("VERIFIED".equals(status)){List<String> mismatch=new ArrayList<>();if(!n(c.getOfferCandidateName()).isBlank()&&!n(c.getName()).equalsIgnoreCase(n(c.getOfferCandidateName())))mismatch.add("Candidate Name");if(!n(c.getOfferPosition()).isBlank()&&!n(c.getPosition()).equalsIgnoreCase(n(c.getOfferPosition())))mismatch.add("Position");if(!n(c.getOfferCompanyName()).isBlank()&&!n(c.getCurrentCompany()).isBlank()&&!n(c.getCurrentCompany()).equalsIgnoreCase(n(c.getOfferCompanyName())))mismatch.add("Company Name");if(!mismatch.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Offer Letter Mismatch Found In: "+String.join(", ",mismatch)+". Mark It As Mismatch Or Correct The Details.");}c.setOfferLetterStatus(status);c.setOfferVerificationRemarks(n(b.get("remarks")));c.setOfferVerifiedBy(u.getName());c.setOfferVerifiedAt(java.time.LocalDateTime.now());risk.calculate(c);Candidate saved=repo.save(c);audit.audit(u.getName(),"OFFER_LETTER_"+status,"CANDIDATE",id.toString(),"Offer Letter Status Changed To "+status);audit.notify("Offer Letter "+status.substring(0,1)+status.substring(1).toLowerCase(),saved.getName()+" Offer Letter Review Was Completed.","FAILED".equals(status)||"MISMATCH".equals(status)?"HIGH":"LOW");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Offer Letter Update - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Offer Letter Verification Updated","Offer letter status: "+status+". Reviewed by "+u.getName()+"."+(n(saved.getOfferVerificationRemarks()).isBlank()?"":" Remarks: "+saved.getOfferVerificationRemarks())));return saved;}
 @PutMapping("/{id}/hire") public Candidate hire(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();if("HIRED".equalsIgnoreCase(c.getHiringStatus()))return c;c.setHiringStatus("HIRED");c.setHiredAt(java.time.LocalDateTime.now());c.setHiredBy(u.getName());Candidate saved=repo.save(c);audit.audit(u.getName(),"CANDIDATE_HIRED","CANDIDATE",id.toString(),saved.getName()+" marked as hired");audit.notify("Candidate hired",saved.getName()+" has been hired for "+saved.getPosition()+".","LOW");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Hiring Update - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Hired","You have been marked as hired for the position of "+saved.getPosition()+". Updated by "+u.getName()+"."));return saved;}
 @PostMapping("/{id}/documents") public DocumentRecord upload(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestParam String type,@RequestParam MultipartFile file)throws Exception{User u=auth.require(h);repo.findById(id).orElseThrow();Files.createDirectories(Path.of(uploadDir));String safe=System.currentTimeMillis()+"-"+file.getOriginalFilename().replaceAll("[^a-zA-Z0-9._-]","_");Path dest=Path.of(uploadDir,safe);file.transferTo(dest);DocumentRecord d=new DocumentRecord();d.setCandidateId(id);d.setType(type);d.setFileName(file.getOriginalFilename());d.setFilePath("/uploads/"+safe);DocumentRecord saved=docs.save(d);audit.audit(u.getName(),"DOCUMENT_UPLOADED","CANDIDATE",id.toString(),type+" uploaded");Candidate candidate=repo.findById(id).orElseThrow();emailService.sendToAll(Arrays.asList(candidate.getEmail(),u.getEmail()),"CrossCheck Document Update - "+candidate.getName(),emailService.candidateMessage(candidate.getName(),"Document Uploaded",type+" was uploaded by "+u.getName()+"."));return saved;}
 private void assertCanModify(User u,Candidate c){boolean admin="ADMIN".equalsIgnoreCase(u.getRole());boolean owner=c.getCreatedByUserId()!=null&&Objects.equals(c.getCreatedByUserId(),u.getId());if(!admin&&!owner)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only The User Who Added This Candidate Or An Admin Can Edit Or Delete It.");}
 private String n(String s){return s==null?"":s;}
}
